def merge_sorted_arrays(left: List[int], right: List[int]) -> List[int]:
    """ Returns a sorted array resulting from the merge of input arrays 'left' and 'right'
    >>> merge_sorted_arrays([], [])
    []
    >>> merge_sorted_arrays([1, 2, 3], [])
    [1, 2, 3]
    >>> merge_sorted_arrays([], [4, 5])
    [4, 5]
    >>> merge_sorted_arrays([1], [4, 5])
    [1, 4, 5]
    >>> merge_sorted_arrays([1, 3, 4], [2, 5])
    [1, 2, 3, 4, 5]
    """
    if not left or not right:
        return left + right
    elif left[-1] >= right[-1]:
        return left + [right[-1]] + merge_sorted_arrays(left[:-1], right[:-1])
    else:
        return [left[-1]] + merge_sorted_arrays(left[:-1], right)


