def is_balanced(paren_string: str) -> bool:
    """ Input to this function is a string containing multiple groups of nested parentheses.
    Return whether the parenthesis groups are balanced.
    A parenthesis group is balanced if all parenthesis in it are properly closed.
    Ignore any spaces in the input string.
    >>> is_balanced('( ) (( )) (( )( ))')
    True
    """
    if not paren_string:
        return True
    stack = []
    for item in paren_string:
        if item == '(':
            stack.append(item)
        elif item == ')':
            if len(stack) < 1:
                return False
            else:
                stack.pop()
    return len(stack) == 0


