def depth_of_parens(paren_string: str, parent: List[int] = []) -> int:
    """ Input to this function is a string of nested parentheses. This function calculates the deepest level of
    nesting for the given string.
    E.g. (()()) would be 2 and ((())) would be 3.
    >>> depth_of_parens('(()()) ((()))')
    2
    """
    maxs = [0, 0]
    for i in range(len(paren_string)):
        if paren_string[i] == "(":
            maxs[0] = max(i + 1, maxs[0])
        else:
            maxs[1] = max(i + 1, maxs[1])
    return max(maxs)


